-- Límites válidos: cantidades cero permitidas y datos tipados sin valores especiales.
SAVEPOINT limites_validos;
UPDATE "Tarjeta" SET "saldo"=0,"puntosAcumulados"=0,"costoAdquisición"=0;
UPDATE "Juego" SET "costo"=0;
UPDATE "Premio" SET "valorAproximado"=0;
UPDATE "Disponer" SET "cantidadDisponible"=0;
UPDATE "RECARGA" SET "monto"=0;
UPDATE "Genrente" SET "salario"=0;
ROLLBACK TO SAVEPOINT limites_validos;
RELEASE SAVEPOINT limites_validos;
